import React, { useContext, useState } from 'react';
import { styled } from '@mui/material/styles';
import Badge from '@mui/material/Badge';
import IconButton from '@mui/material/IconButton';
import Button from '@mui/material/Button';
import MenuIcon from '@mui/icons-material/Menu';
import NotificationsIcon from '@mui/icons-material/Notifications';
import ShoppingBagIcon from '@mui/icons-material/ShoppingBag';


import Dialog from '@mui/material/Dialog';
import AppBar from '@mui/material/AppBar';
import Toolbar from '@mui/material/Toolbar';
import Typography from '@mui/material/Typography';
import CloseIcon from '@mui/icons-material/Close';
import Slide from '@mui/material/Slide';

import { AiOutlineMenuFold, AiOutlineMenuUnfold } from "react-icons/ai";
import {
  Avatar,
  ListItemIcon,
  Menu,
  MenuItem,
} from '@mui/material';
import {
  AccountBoxOutlined,
  Logout,
} from '@mui/icons-material';
import { useNavigate, Link } from 'react-router-dom';
import { MyContext } from '../../App';
import { fetchDataFromApi } from '../../utils/api';
import AddProducts from '../../Pages/Products/AddProducts';
// import EditProduct from '../../Pages/Products/EditProduct';
import AddCategory from '../../Pages/AddCategory';
import AddSliders from '../../Pages/HomesliderBanner/AddSliders';
import AddnewCategory from '../../Pages/AddCategory/AddnewCategory';
import AddSubNewCategory from '../../Pages/AddCategory/AddSubNewCategory';
import AddAddress from '../../Pages/Address/AddAddress';
import EditCategory from '../../Pages/AddCategory/EditCategory';
import EditProduct from '../../Pages/Products/editProduct';
import AddWeight from '../../Pages/Products/AddWeight';
import AddSize from '../../Pages/Products/AddSize';
import AddRam from '../../Pages/Products/AddRam';
import EditRam from '../../Pages/Products/EditRam';
import EditSize from '../../Pages/Products/EditSize';
import EditWet from '../../Pages/Products/EditWet';
import AddBlog from '../../Pages/Blog/AddBlog';
import Editblo from '../../Pages/Blog/EditBlo';
import BDetails from '../../Pages/Blog/BDeatils';

const StyledBadge = styled(Badge)(({ theme }) => ({
  '& .MuiBadge-badge': {
    right: -3,
    top: 13,
    border: `2px solid ${theme.palette.background.paper}`,
    padding: '0 4px',
  },
}));
const Transition = React.forwardRef(function Transition(props, ref) {
  return <Slide direction="up" ref={ref} {...props} />;
});
function Header() {
  const context = useContext(MyContext);
  const history = useNavigate();
  const [anchorEl, setAnchorEl] = useState(null);
  const open = Boolean(anchorEl);

  const handleClick = (event) => {
    setAnchorEl(event.currentTarget);
  };
  const handleClose = () => {
    setAnchorEl(null);
  };

  const handleLoginform = () => {
    history("/login");
  };

  const logOUThandler = () => {

    fetchDataFromApi(`/api/user/logout?token=${localStorage.getItem("accesstoken")}`, { withCredentials: true })
      .then((res) => {
        
  if (res?.message === "Unauthorized access") {

          history("/login");
        }




        if (res?.error === false) {
          context.setisLogin(false);
          localStorage.removeItem("accesstoken");
